(function (all) { var mine = all["ar"] = all["ar"] || {}; var add = {"manual.831d0f72d242":"البدء","manual.f2f53974b760":"Freally Capture استوديو لسطح المكتب يعمل على Windows وmacOS وLinux. يصف هذا الدليل الإصدار 1.2.1، وهو الإصدار الحالي.","manual.4b5f10daa08b":"افتح Freally Capture. في المرة الأولى، يطلب منك قبول اتفاقية الترخيص الخاصة به؛ ثم يفحص معالج إعداد بطاقة الرسومات والمعالج لديك، ويقترح مُرمِّزًا وحجمًا للوحة ومعدل بت، مع ذكر سبب كل اقتراح.","manual.fe88634050bf":"يُفتح الاستوديو على معاينة البرنامج مع أرصفة <strong>المشاهد</strong> و<strong>المصادر</strong> و<strong>المازج</strong> و<strong>عناصر التحكم</strong>. لا يوجد حساب ولا تسجيل دخول.","manual.4c937d2528ca":"على <strong>macOS</strong>، اسمح بـ<strong>تسجيل الشاشة</strong> — وكذلك <strong>الكاميرا</strong> و<strong>الميكروفون</strong> إن كنت تستخدمهما — من إعدادات النظام ← الخصوصية والأمن، ثم أعد فتح التطبيق. وعلى <strong>Linux مع Wayland</strong>، يسألك مربع الحوار الخاص بسطح المكتب عن الشاشة أو النافذة التي تريد مشاركتها.","manual.adc8f305f8f8":"أضف مصدرك الأول (راجع <a href=\"#build-a-scene\">إنشاء مشهد</a>) وستكون جاهزًا للتسجيل أو البث المباشر.","manual.46e49bd74b1d":"إنشاء مشهد","manual.f779d891c1f2":"المشهد مجموعة مكدّسة من المصادر تُركَّب على بطاقة الرسومات. ويمكن لعدة مشاهد أن تتشارك مصدرًا واحدًا.","manual.5a1c5f778fdb":"في رصيف <strong>المصادر</strong>، انقر <strong>إضافة مصدر</strong> واختر نوعًا: <strong>شاشة</strong> أو <strong>نافذة</strong> أو <strong>لعبة</strong> أو <strong>كاميرا ويب / بطاقة التقاط</strong> أو <strong>متصفح</strong> أو <strong>وسائط</strong> أو <strong>صورة</strong> أو <strong>نص</strong> أو <strong>لون</strong> أو <strong>الصوت</strong>.","manual.2a2d9e2015b5":"أضف <strong>التقاط الشاشة</strong>: تمتلئ معاينة البرنامج بشاشتك.","manual.80c8e9c8176f":"أضف مصدر <strong>كاميرا ويب</strong>، واسحبه إلى أحد أركان اللوحة، وغيّر حجمه باستخدام مقابضه.","manual.264150f36676":"أضف تراكب <strong>صورة</strong> أو <strong>متصفح</strong> في الأعلى. ترتيب القائمة هو الترتيب على اللوحة: العنصر الأعلى في القائمة هو الأقرب إلى الواجهة.","manual.a329c46899d6":"أنشئ مزيدًا من المشاهد في رصيف <strong>المشاهد</strong> — مثل «يبدأ قريبًا» و«اللعب» و«سأعود حالًا» — وبدّل بينها.","manual.9c8d5730d1bb":"<strong>نصيحة:</strong> غيّر خصائص مصدر مشترك مرة واحدة، فتتغير في كل مشهد يستخدمه.","manual.fd869e76d280":"<strong>المعاينة:</strong> على Windows وmacOS وLinux مع X11، تُرسم معاينة البرنامج مباشرةً من بطاقة الرسومات، لذا يبدو السحب وتغيير الحجم والتدوير فوريًا. أما على Wayland فتُستخدم معاينة قياسية، مع إمكانات التحرير ذاتها على اللوحة.","manual.87eca68fecaa":"الفلاتر والانتقالات","manual.36a962cf3902":"كدّس الفلاتر على كل مصدر، على بطاقة الرسومات، واختر الطريقة التي يُفسح بها مشهد المجال للمشهد التالي.","manual.4708b4dbab34":"إضافة مفتاح كروما","manual.9df34cebcaf5":"انقر بزر الماوس الأيمن على مصدر — كاميرا أمام شاشة خضراء مثلًا — واختر <strong>الفلاتر</strong>.","manual.9981601a6174":"أضف <strong>مفتاح الكروما</strong> واضبط <strong>لون المفتاح</strong> و<strong>التشابه</strong> و<strong>النعومة</strong> و<strong>التسرّب</strong>: يختفي اللون المستبعَد مباشرةً على اللوحة.","manual.b76bd309a9f6":"أضف مزيدًا من الفلاتر حسب حاجتك — <strong>تصحيح الألوان</strong> و<strong>LUT</strong> و<strong>تمويه</strong> و<strong>قناع</strong> و<strong>زيادة الحدّة</strong> — واسحبها لإعادة ترتيب السلسلة.","manual.db41fe5a40e4":"ضبط انتقال","manual.bea9e11be98d":"في <strong>عناصر التحكم</strong>، افتح أداة اختيار الانتقال، واختر <strong>قطع</strong> أو <strong>تلاشٍ</strong> أو <strong>انزلاق</strong> أو <strong>سحب جانبي</strong> أو <strong>Stinger</strong> أو <strong>مسح الإضاءة</strong>، ثم حدّد مدة.","manual.eada58ce5b2e":"بالنسبة إلى <strong>Stinger</strong>، اختر الوسائط ونقطة الانتقال الخاصة بها؛ وبالنسبة إلى <strong>مسح الإضاءة</strong>، اختر التدرّج ودرجة نعومته.","manual.79756cb8b209":"بدّل المشاهد لترى الانتقال وهو يُعرض. وفي وضع الاستوديو، يُعرض الانتقال عندما ترسل المعاينة إلى البرنامج.","manual.2c0c025b4264":"المُركِّب والمؤثرات المرئية","manual.b768e85eff32":"إمالة ثلاثية الأبعاد، ومفاتيح الإخراج النهائي، والتجميد والاستنساخ، ومجموعة من أنواع التمويه، وانتقالات حركية بقواعد، واستوديو للمظللات، وأقنعة بيزيه، وانتقالات Stinger بقناع المسار.","manual.d2b720eca5a5":"الإمالة ثلاثية الأبعاد والمنظور","manual.d665cc2f2296":"افتح <strong>تعديل التحويل</strong> على عنصر، واضبط <strong>الإمالة X</strong> و<strong>الإمالة Y</strong> وشدة <strong>المنظور</strong> لتثبيت المصدر في فضاء ثلاثي الأبعاد. أما التحويل الخالي من الإمالة فيُعرض تمامًا كما كان من قبل.","manual.c4077ba2b72d":"مفاتيح الإخراج النهائي","manual.d4220af54ed9":"افتح <strong>أدوات ← مفاتيح الإخراج النهائي</strong> وأضف أي مصدر كطبقة فوق <strong>مخرج البرنامج</strong>، فوق كل مشهد وعبر كل تبديل للمشاهد — شعار محطة، أو شارة «مباشر»، أو شريط تعريفي سفلي.","manual.0677e571c1f8":"أعد ترتيب الطبقات، واضبط لكل منها العتامة والموضع والحجم والتشغيل أو الإيقاف. وهي تظهر في المعاينة والتسجيل والبث والعرض المتعدد على حد سواء.","manual.1e484119e149":"تجميد الإطار واستنساخ المصادر","manual.4cdb8e22f58b":"انقر بزر الماوس الأيمن على مصدر، وافتح <strong>الفلاتر</strong> وأضف <strong>تجميد</strong>: يثبّت آخر إطار في البرنامج والمعاينة والتسجيل والبث معًا. أوقفه لإلغاء التجميد.","manual.59fd957b48dc":"انقر زر <strong>استنساخ</strong> (⧉) في صف المصدر لوضع تغذية واحدة في عدة مشاهد أو مواضع، ولكل نسخة مستنسخة تحويلها وفلاترها الخاصة.","manual.a90410d6b30c":"أنواع التمويه","manual.eeb69e428aa3":"في <strong>الفلاتر</strong> الخاصة بمصدر، أضف أحد أنواع التمويه إلى جانب التمويه الغاوسي: <strong>اتجاهي</strong> (أثر حركة بزاوية)، أو <strong>شعاعي</strong> (دوران حول مركز)، أو <strong>التقريب</strong> (أثر تقريب بأسلوب dolly-zoom)، أو <strong>تحويل إلى بكسل</strong> (فسيفساء).","manual.54261c9f6b8f":"انتقال النقل وقواعد الانتقال","manual.ef17a04962be":"اختر انتقال <strong>النقل</strong>: تنساب العناصر الموجودة في المشهدين كليهما من موضعها وحجمها ودورانها واقتصاصها القديمة إلى الجديدة بدلًا من القطع، أما العناصر الموجودة في مشهد واحد فقط فتظهر أو تختفي بالتلاشي.","manual.e31792f9e737":"افتح <strong>أدوات ← قواعد الانتقال</strong> لتمنح زوجًا من المشاهد انتقالًا ومدة خاصين به. ولدخول عنصر بعينه، اضبط ظهورًا تدريجيًا عبر <strong>الكشف</strong> ضمن <strong>تعديل التحويل</strong>.","manual.bb4e30a1ea68":"استوديو مظللات WGSL","manual.e475acf03bea":"أضف <strong>تأثير WGSL من إنشاء المستخدم</strong> كفلتر وحرّره مباشرةً. تُنشأ أشرطة التمرير الخاصة به من تعليقات <code>// @param</code> التوضيحية، ويضم معرض مدمج تأثيرات التدرج الرمادي والعكس وخطوط المسح والتظليل الطرفي.","manual.424ca3316822":"<strong>نصيحة:</strong> يُترجَم المظلل ويُتحقق منه أثناء الكتابة. ويُتجاهل المظلل غير الصالح ويُعرض المصدر دون فلترة — ولا يحدث انهيار أبدًا.","manual.c24e8b5ee2c0":"أقنعة بيزيه","manual.37870edaacbc":"أضف فلتر <strong>القناع الحر</strong> وارسم مسارًا مغلقًا: اسحب المقابض، وانقر نقرًا مزدوجًا لإضافة نقطة، وانقر بزر الماوس الأيمن لإزالة نقطة. ويتضمن أشكالًا مسبقة الضبط، وتنعيمًا لكل حافة، وخيار العكس.","manual.f44ad1306530":"صدّر أي مسار كنمط <strong>مسح الإضاءة</strong> بتدرج رمادي لإعادة استخدام الشكل كانتقال.","manual.e4c8b0c52b3e":"انتقالات Stinger بقناع المسار","manual.b35494db6ce6":"اضبط انتقال Stinger ليحمل شفافيته على شكل <strong>قناع المسار</strong>، مع وضع التعبئة والقناع <strong>جنبًا إلى جنب</strong> أو بشكل <strong>مكدّس</strong>، كي تصمد الشفافية مع برامج الترميز التي تُسقطها (H.264 وHEVC). ويمكنك اختياريًا <strong>خفض صوت البرنامج</strong> تحت صوت Stinger نفسه أثناء تشغيله.","manual.3879f0c73d18":"التراكبات والمزيد من المصادر","manual.cea21c089e39":"الإعادة، وقوائم التشغيل، والعناوين، والمقاييس، وتراكب للإحصاءات، والمؤقّتات، وتراكب للإدخال، وتغذيتان عبر الشبكة، وكلها من قائمة <strong>+ / إضافة مصدر</strong> في رصيف <strong>المصادر</strong>.","manual.4a459b922e4b":"الإعادة الفورية","manual.2e042aa67065":"جهّز مخزن الإعادة أولًا (<strong>تجهيز الإعادة</strong> في رصيف <strong>عناصر التحكم</strong>)، ثم اختر <strong>إعادة فورية</strong> من <strong>+ / إضافة مصدر</strong> وضعها في مشهد.","manual.d7645da473a6":"أدخِل الثواني الأخيرة إلى البرنامج باختصار الإعادة الخاص بك — تُنسخ دون إعادة ترميز وتُعرض بسرعة <strong>100%</strong> أو <strong>50%</strong> أو <strong>25%</strong>، مُبطَّأةً بدلًا من اختلاق إطارات. ويمكنك التنقل فيها أو إيقافها مؤقتًا أثناء العرض.","manual.5b8095e70de0":"في النهاية يُفرغ المصدر نفسه، فيعود العرض إلى البث المباشر من تلقاء نفسه.","manual.6433eaab9b10":"<strong>نصيحة:</strong> الإعادة بالحركة البطيئة صامتة عن قصد: فالصوت المُبطَّأ سيكون مشوّهًا، لذا يُستبعد بدلًا من تزييفه.","manual.f0b63d46cd74":"قائمة تشغيل الوسائط والموسيقى الخلفية","manual.37ed12f9d130":"أضف <strong>قائمة تشغيل وسائط (بدون فجوات)</strong> وأنشئ قائمة مرتبة بنقاط بداية ونهاية ونقاط إشارة لكل عنصر. تُشغَّل القائمة كلها عبر مفكّك ترميز واحد، لذا تكون الوصلات دقيقة على مستوى الإطار وخالية من الفجوات فعلًا.","manual.ef41fa6ad9b5":"اختر طريقة تشغيلها — <strong>تكرار</strong> أو <strong>عشوائي</strong> أو <strong>إبقاء الأخير</strong> — وتنقّل فيها باختصارَي التالي والسابق. تعرض قائمة التشغيل الصوتية فقط <strong>اسم المقطع الحالي</strong> على اللوحة، وتُشغَّل عبر شريطها الخاص في المازج؛ انقر زر <strong>المراقبة</strong> في ذلك الشريط لتسمعها.","manual.6e641ae2bd92":"أما للموسيقى التي تُشغَّل دون أي شيء على الشاشة، فاختر بدلًا من ذلك <strong>+ / إضافة مصدر ← موسيقى خلفية…</strong> واختر ملفًا أو أكثر من نوع <code>.mp3</code> أو <code>.wav</code> أو <code>.flac</code>، مع ترتيب عشوائي إن أردت. وهي تكتم الصوت الخاص بخلفية الفيديو، فلا يُسمع أبدًا سوى مصدر واحد.","manual.b9aad55133bf":"مصمم العناوين ولوحات النتائج","manual.5382c093aaef":"أضف <strong>عنوان / لوحة نتائج</strong> لفتح المصمم: كدّس طبقات <strong>النص</strong> و<strong>الصورة</strong> و<strong>الشكل</strong>، مع نص بحدود وظلال، وحركات دخول وخروج (تلاشٍ، انزلاق، مسح).","manual.7b8fea70655a":"اربط الحقول بملف مراقَب (خلية CSV أو مؤشر JSON) أو بمتغير من متغيرات الاستوديو، ثم تحكّم فيه مباشرةً: غيّر اسمًا، أو عدّل النتيجة، أو شغّل الحركة دون لمس المشهد.","manual.88a9422e37a9":"مُصوِّر الصوت","manual.87f4a5bdd624":"أضف <strong>مُصوِّر الصوت</strong> واختر نمطًا — <strong>أعمدة الطيف</strong> أو <strong>راسم الذبذبات</strong> أو <strong>مقاييس VU</strong> الاستريو — ثم اربطه بأي شريط في المازج أو مسار أو المزيج الرئيسي. وهو يعرض صوت فيديو الخلفية أيضًا.","manual.0ae90a461adb":"في <strong>الخصائص</strong> الخاصة بالمصدر، فعّل <strong>ألوان كلاسيكية</strong> للحصول على نطاقات الأخضر والأصفر والأحمر، أو اتركه معطَّلًا للحصول على لون واحد ثابت. وتجد هناك أيضًا الحجم وعدد الأعمدة ومعدل الهبوط.","manual.0d1ceffb08ba":"<strong>نصيحة:</strong> يستمع المُصوِّر <strong>بعد مُنزلِق المستوى (Fader)</strong>، لذا يظهر المصدر المكتوم مسطحًا: فهو يعرض بالضبط ما تسمعه.","manual.ec642e1cf0cc":"تراكب الإحصاءات ومؤقّت التقسيمات وتراكب الإدخال","manual.6b4fe6f81cb0":"أضف <strong>إحصاءات الأداء (HUD)</strong> لعرض الأرقام المقيسة في رصيف الإحصاءات على اللوحة — عدد الإطارات في الثانية، والمعالج، والذاكرة، ووقت التركيب على GPU، والإطارات المُسقَطة، ومعدل البت المباشر — مع إمكانية تشغيل كل سطر أو إيقافه. ويُستبعد استخدام GPU عن قصد، لأنه لا يُقاس.","manual.cbd8a4b88736":"أضف <strong>مؤقّت تقسيمات السرعة</strong>، واستورد ملف LiveSplit <code>.lss</code>، وشغّله باختصارات عامة للتقسيم والتراجع والتخطي وإعادة الضبط، مقارنةً بأفضل أداء شخصي لك أو أفضل المقاطع أو المتوسط. يُقرأ الملف فقط؛ ولا تُكتب أي محاولة إليه أبدًا.","manual.fbf4bbeaf903":"أضف <strong>تراكب الإدخال (المفاتيح/وحدة التحكم)</strong> لعرض لوحة المفاتيح والماوس ووحدة تحكم الألعاب مباشرةً، بأحد أربعة تخطيطات (WASD، أو لوحة مفاتيح مدمجة، أو وحدة تحكم بعصوين، أو عصا قتال بثمانية اتجاهات). تعمل لوحة المفاتيح والماوس على Windows؛ أما وحدات تحكم الألعاب فتعمل على الأنظمة الثلاثة كلها.","manual.bf794edb3c25":"شريط التواصل الاجتماعي والقنوات","manual.5f898056ef11":"أضف <strong>شريط التواصل الاجتماعي</strong> من <strong>+ / إضافة مصدر</strong>: لوحة تعرض حساباتك. اختر منصة لكل صف — <strong>YouTube وTwitch وKick وX وInstagram وTikTok وFacebook وDiscord</strong> كشارات ملونة، أو <strong>مخصص</strong> بتسمية ولون من اختيارك — واكتب اسم الحساب (مثل <code>@mychannel</code>). أضف سطر عنوان اختياريًا («تابعني»)، وأعد ترتيب الصفوف، واضبط حجم النص وألوانه.","manual.1dab9389547a":"يبقى كل حقل قابلًا للتحرير في <strong>الخصائص</strong> الخاصة بالمصدر. وتُتخطى الصفوف التي لا تحتوي على اسم حساب، لذا يمكنك الاحتفاظ بقائمة كاملة وملء ما تستخدمه فقط.","manual.1a4ac3c2e0bf":"رسالة الدردشة المميزة","manual.c5d58a7d58be":"افتح <strong>أدوات ← رسالة دردشة مميزة…</strong> (أو لوحة الأوامر). تسرد النافذة أحدث الأسطر من كل تراكب دردشة قيد التشغيل: انقر <strong>تمييز</strong> على أحدها لتثبيته في البرنامج كلافتة يراها مشاهدو البث والتسجيل.","manual.162d364796a2":"اضبط ألوان <strong>اللافتة</strong> و<strong>النص</strong> في مربع الحوار، وانقر <strong>مسح</strong> لإزالتها من الهواء. ويُزال التثبيت نفسه عند إعادة التشغيل، وذلك عن قصد: فلن تلاحق تحية الأمس عرض اليوم أبدًا.","manual.89a84c53e014":"إبراز المؤشر وتأثيرات النقر","manual.d0a5d9fb047d":"انقر بزر الماوس الأيمن على التقاط شاشة أو نافذة، وافتح <strong>الفلاتر</strong> وأضف <strong>تأثيرات المؤشر</strong>: <strong>هالة المؤشر</strong> (اللون ونصف القطر)، و<strong>موجات النقر</strong> للزرين الأيسر والأيمن بألوان مميزة، و<strong>عرض ضغطات المفاتيح</strong> اختياريًا بجوار المؤشر. تظهر التغييرات مباشرةً.","manual.4a17c44757e4":"<strong>ملاحظة:</strong> تعمل تأثيرات المؤشر على Windows فقط؛ إذ يرسم macOS وLinux المؤشر بنفسيهما. يقرأ تراكب الإدخال وعرض ضغطات المفاتيح الإدخال <strong>فقط أثناء تشغيلهما</strong>، ويرسمانه مباشرةً في الصورة: لا يُخزَّن شيء ولا يُسجَّل.","manual.8bdb1aadf964":"مصادر الشبكة: الاستقبال عبر الشبكة المحلية وFreally Link","manual.797fe86a1fe8":"أضف <strong>استقبال الشبكة المحلية (مستمع SRT/RTMP)</strong> لفتح مستمع على هذا الكمبيوتر، ثم وجّه تطبيق كاميرا على هاتف، أو مُرمِّزًا، أو كمبيوترًا ثانيًا إلى العنوان المعروض (مع رمز QR). يظهر في المشهد مع شريطه الخاص في المازج. يمكن أن يحمل SRT عبارة مرور AES اختيارية؛ أما RTMP فلا يملك مصادقة خاصة به، لذا يفضّل النموذج SRT.","manual.e2761818ccef":"للمشاركة بين نسختين من Freally Capture، فعّل مخرج <strong>Freally Link</strong> على الكمبيوتر <strong>المُرسِل</strong> واضبط <strong>مفتاح الاقتران</strong> الخاص به — إذ لا يمكن تفعيله بدونه. وعلى الكمبيوتر <strong>المستقبِل</strong>، أضف <strong>Freally Link (نسخة أخرى)</strong>، وانقر <strong>فحص الشبكة المحلية</strong> واكتب المفتاح: يظهر برنامج المُرسِل كمصدر. لا يحتاج أي من الطرفين إلى ffmpeg، ولا يرى المستقبِل الذي لا يملك المفتاح أي إطار أبدًا.","manual.a793cb271e32":"<strong>ملاحظة:</strong> يبقى مصدرا الشبكة كلاهما <strong>معطَّلين حتى تضيفهما</strong>، ويظلان ضمن شبكتك الخاصة، ولا يلمسان الإنترنت أبدًا: لا شيء يعثر عليك، ولا شيء يتصل بالخارج.","manual.de10be5dcf2c":"العد التنازلي «يبدأ قريبًا»","manual.71b47ef78ea4":"شاشة انتظار قبل العرض بنقرة واحدة: عدّ تنازلي كبير حتى موعد العرض فوق صورة أو GIF أو فيديو أو تدرّج أو موسيقى، يومض عند الصفر وينتظرك لتنتقل إلى العرض.","manual.303493002776":"إضافة العد التنازلي","manual.f78f2994b5d5":"في رصيف <strong>المصادر</strong>، افتح <strong>+ / إضافة مصدر</strong> واختر <strong>يبدأ قريبًا…</strong>. يضع ذلك في المشهد عدًّا تنازليًا يملأ اللوحة بالكامل — تسمية توضيحية فوق رقم كبير.","manual.c4bff5a4f06e":"اكتب <strong>التسمية التوضيحية</strong> («يبدأ قريبًا»، «سأعود حالًا»)، ثم اضبط الوقت باستخدام <strong>منتقي الساعة</strong>: <strong>ساعة</strong> (1–12)، و<strong>دقيقة</strong> بخطوات من خمس دقائق، و<strong>AM</strong> أو <strong>PM</strong> (صباحًا أو مساءً). يعدّ المصدر تنازليًا حتى ذلك الوقت من اليوم.","manual.59b00df516f1":"عند الصفر، <strong>يومض العد التنازلي ويثبت عند 0:00:00</strong> — ولا يبدّل المشاهد من تلقاء نفسه أبدًا. انتقل إلى مشهدك المباشر حين تكون جاهزًا. ويبقى كل حقل قابلًا للتحرير في <strong>الخصائص</strong> الخاصة بالمصدر.","manual.1dfb2d817d39":"اختيار خلفية","manual.edc2450aeecd":"اختر التعبئة: <strong>تدرّج</strong> بلونين (الافتراضي)، أو لون <strong>ثابت</strong>، أو <strong>صورة</strong> (انقر <strong>تصفّح…</strong>)، أو <strong>شفاف</strong> للسماح لمصدر أسفله بالظهور.","manual.07a5fd9ac032":"اختر ملف <strong>GIF</strong> أو <strong>فيديو</strong> فيتكرر خلف الأرقام، <strong>بحجم ملائم وفي المنتصف</strong>، فتظهر الصورة كاملة دون أي اقتصاص.","manual.1cda5be75376":"أضف <strong>موسيقى خلفية</strong> من زر <strong>تصفّح…</strong> في مربع الحوار (MP3 أو WAV أو FLAC أو M4A أو AAC أو OGG أو Opus). تتكرر الموسيقى، وتسمعها في المعاينة، وهي جزء من التسجيل والبث. ويُكتم الصوت الخاص بخلفية الفيديو، فلا يُسمع أبدًا سوى مصدر واحد.","manual.b39b6b7add20":"<strong>نصيحة:</strong> للحصول على موسيقى خلف شاشة بسيطة، اترك الخلفية على «تدرّج» أو «شفاف» وأضف الموسيقى: عدّ تنازلي نظيف مع موسيقى تصويرية.","manual.84f506f4fca5":"مازج الصوت","manual.480e299c8728":"امزج كل مصدر صوتي، وأرسله إلى ما يصل إلى 6 مسارات، ونقِّ صوت الميكروفون — كل ذلك مباشرةً.","manual.bcbc220b3e63":"كل مصدر صوتي هو شريط في <strong>المازج</strong>: اسمه، ومقياس المستوى، ومُنزلِق المستوى، والكتم، والمراقبة، والفلاتر، ونقاط المسارات (1–6).","manual.03b920dc5376":"اسحب مُنزلِق المستوى لضبط المستوى، وانقر <strong>كتم</strong> أو <strong>المراقبة</strong>، وأرسل المصدر إلى أي من المسارات الستة.","manual.9a9991c7dc36":"افتح <strong>الفلاتر</strong> الخاصة بمصدر وأضف <strong>إزالة الضوضاء</strong> (معالجة إشارات كلاسيكية، دون ذكاء اصطناعي)، أو <strong>بوابة ضوضاء</strong>، أو <strong>ضاغط</strong>، أو <strong>مُحدِّد</strong>، أو <strong>مُعادِل (EQ)</strong>، أو <strong>الكسب</strong>.","manual.1a58b91bc5aa":"اربط اختصار <strong>اضغط للتحدث</strong> أو <strong>اضغط للكتم</strong>، وراقب مقياس <strong>LUFS</strong> لمعرفة جهارة البرنامج.","manual.7158a36ed4d5":"<strong>ملاحظة لـ macOS:</strong> لا يمنح macOS التطبيقات «ما تسمعه» من تلقاء نفسه. استخدم صوت ScreenCaptureKit (macOS 13 أو أحدث) حيثما كان متاحًا، أو ثبّت جهازًا افتراضيًا مثل BlackHole واختره مصدرًا لصوت النظام. يرشدك Freally Capture، ويواصل التسجيل حتى إن تعذّر فتح أحد المصادر.","manual.bfdd510698ef":"التسجيل","manual.e39b756fce99":"سجّل البرنامج على عدة مسارات باستخدام المُرمِّز العتادي لبطاقة الرسومات، أو بلا فقدان بالصيغة الخاصة بـ Capture.","manual.ad438c2dbf4b":"في <strong>الإعدادات ← الخرج</strong>، اختر مُرمِّزًا. يعثر Freally Capture على <strong>NVENC</strong> أو <strong>Quick Sync</strong> أو <strong>AMF</strong> أو <strong>VAAPI</strong> أو <strong>VideoToolbox</strong> ويختار الأفضل؛ ويبقى <strong>x264</strong> على المعالج متاحًا دائمًا كخيار احتياطي.","manual.3bc1870f8449":"اختر حاوية — <strong>MP4</strong> أو <strong>MKV</strong> أو <strong>MOV</strong> أو <strong>WebM</strong> — أو صيغة <strong>freally-video</strong> الخاصة بـ Capture بلا فقدان (<code>.frec</code>)، التي لا تحتاج إلى تثبيت أي شيء آخر.","manual.e2a332927058":"أرسل المصادر إلى المسارات الصوتية (حتى 6) كي يبقى الميكروفون وصوت النظام وضيوفك منفصلين عند التحرير. ويمكنك اختياريًا تفعيل <strong>تقسيم الملفات</strong> و<strong>نسخة محلية بمسارات منفصلة أثناء البث</strong>.","manual.e0fa2f5a9430":"انقر <strong>بدء التسجيل</strong> في <strong>عناصر التحكم</strong>. تعرض نقطة <strong>REC</strong> خضراء الوقت وعدد المسارات. انقر <strong>إيقاف</strong> لإنهاء الملف.","manual.b1eb969490f1":"<strong>ملاحظة حول برامج الترميز:</strong> يستخدم MP4 مع H.264 وAAC (وكذلك HEVC أو AV1) برامج ترميز تشملها براءات اختراع، ويوفرها <strong>ffmpeg</strong>، وهو <em>غير مُضمَّن</em>: يُنزّله Freally Capture في أول مرة تحتاج إليه ويتحقق منه. أما صيغة <strong>freally-video</strong> بلا فقدان فلا تحتاج إلى تنزيل أي شيء.","manual.691bff5377a8":"إمكانات متقدمة للتسجيل والإعادة","manual.3c2d08430816":"كل ما يحيط بالملف: تسجيلات منفصلة لكل مصدر، وأداة لقص المقاطع، وشفافية حقيقية، وتقسيم وعلامات عند الأحداث، ومهام بعد التسجيل، وفحص للسلامة، ورمز توقيت SMPTE. كل ذلك معطَّل حتى تفعّله، ولا يتصل أي منه بالإنترنت.","manual.537ffa2b9063":"تسجيل ISO لكل مصدر","manual.e57aa725fa41":"افتح <strong>الإعدادات ← الخرج</strong> وابحث عن <strong>تسجيل ISO</strong>. فعّل <strong>تسجيل «{name}» كملف ISO مستقل</strong> لكل مصدر تريد تسجيله نظيفًا: يُسجَّل كلٌّ منها قبل التركيب، بحجم اللوحة ومعدل إطاراتها، لذا يتطابق كل ملف مع البرنامج على الخط الزمني للتحرير. وكل ضيف عن بُعد هو مصدر، لذا يحصل كل ضيف على ملف أيضًا.","manual.4bce8f25ec9c":"اترك <strong>التسجيل مع فلاتر المصدر</strong> محدَّدًا للحصول على المظهر المعالَج، أو ألغِ تحديده للحصول على المصدر الخام، واختر <strong>صيغة ISO</strong> و<strong>مرمّز فيديو ISO</strong> لكل تسجيل. يُؤخذ الصوت بعد الفلاتر ولكن قبل مُنزلِق المستوى والكتم، لذا لا يُسكِت أي قرار في المزج ملف ISO أبدًا.","manual.7f29ae4e2c55":"<strong>نصيحة:</strong> يعمل تسجيلا ISO بارتياح على بطاقة رسومات متوسطة الفئة؛ وكل تسجيل إضافي يكلّف عملية عرض وترميز أخرى، وتذكر لوحة الإعدادات ذلك.","manual.b2aad668b8b9":"أداة قصّ الإعادات والمقاطع","manual.c8af16e1cd4f":"افتح تسجيلًا محفوظًا في نافذة <strong>قصّ</strong> من قائمة التسجيلات، وتنقّل فيه باستخدام <strong>إطار للخلف</strong> و<strong>إطار للأمام</strong>، وحدّد نقاطك باستخدام <strong>نقطة البداية</strong> و<strong>نقطة النهاية</strong> أثناء المشاهدة.","manual.1f80dfd03a36":"تحقّق من الشارة قبل التصدير. تعني الشارة الخضراء <em>«يُصدَّر دون إعادة ترميز»</em> أن نقطة البداية تقع على إطار مفتاحي (شبه فوري وبلا فقدان)؛ أما الشارة الكهرمانية فتحذّر من أن الترميز سيُعاد — اضغط <strong>إطار مفتاحي</strong> لمحاذاة نقطة البداية والحصول على قص بلا فقدان. انقر <strong>تصدير المقطع</strong>، أو <strong>9:16</strong> لتصدير نسخة رأسية.","manual.8a92b0b480f4":"التسجيل مع الشفافية","manual.79bfd450e6aa":"في <strong>الإعدادات ← الخرج</strong>، فعّل <strong>التسجيل مع الشفافية (ألفا)</strong> لتسجيل البرنامج فوق خلفية شفافة بصيغة <code>.frec</code> الخاصة بـ Capture. يحصل التسجيل على عملية عرض شفافة خاصة به، لذا تحتفظ المعاينة والبث بالصورة العادية. ومن قائمة التسجيلات، صدّر ملف <code>.mov</code> بصيغة <strong>ProRes 4444</strong> أو <strong>QuickTime Animation (QTRLE)</strong> لبرنامج التحرير لديك؛ أما MP4 وMKV فيُسطّحان الشفافية.","manual.fade0a9d0454":"<strong>ملاحظة:</strong> الشفافية مجرد علم في ترويسة <code>.frec</code>، لذا تُشغَّل هذه الملفات في كل مكان يُشغَّل فيه <code>.frec</code>، وتُفتح الملفات الأقدم على أنها معتمة.","manual.33e5c9a96c5d":"التقسيم والعلامات التلقائية","manual.5596d47693a3":"في إعدادات التقسيم الخاصة بـ <code>.frec</code>، اختر بدء ملف جديد عند <strong>تبديل المشهد</strong> أو <strong>علامة</strong> أو <strong>خطوة سير العرض</strong>. يبدأ كل جزء عند الإطار الدقيق لذلك الحدث، ويستمر الجزء ثانية واحدة على الأقل، لذا لا يمكن لدفعة من الأحداث أن تُنشئ كومة من الملفات الصغيرة جدًا.","manual.7fc20a49c196":"فعّل <strong>إضافة علامات الفصول تلقائيًا عند أحداث الاستوديو</strong> لتمييز تبديلات المشاهد، والإعادات المحفوظة، وعمليات إعادة الاتصال، ودفعات الإطارات المُسقَطة، والتنبيهات، وإجراءات القواعد كفصول. تُضاف إلى عناوين فصول MKV وإلى ملف <code>.chapters.txt</code> بجوار التسجيل، إلى جانب العلامات التي تضعها باختصارك.","manual.519fceb746f3":"بعد التسجيل: خط الأنابيب وفحص السلامة","manual.561bb55d7a18":"أنشئ <strong>خط أنابيب ما بعد التسجيل</strong> لكل ملف تعريف من مجموعة ثابتة من الخطوات — <strong>تحقّق</strong> و<strong>إعادة تغليف إلى MP4</strong> و<strong>معايرة الصوت</strong> و<strong>إعادة تسمية</strong> و<strong>نقل إلى مجلد</strong> و<strong>نسخ إلى مجلد</strong> و<strong>إظهار في مدير الملفات</strong> و<strong>إخطار سكربتات Lua</strong>. يعمل في الخلفية مع قائمة انتظار مباشرة ويتوقف عند أول فشل. ولا توجد عن قصد خطوة «تشغيل أي أمر».","manual.2f93cddd1f21":"شغّل فحص السلامة بعد التسجيل أو متى شئت، للحصول على نتيجة واضحة — سليم أو تحذير أو فشل — بشأن <strong>الحاوية</strong> و<strong>استمرارية الفيديو</strong> و<strong>استمرارية الصوت</strong> و<strong>تداخل الصوت والفيديو</strong> و<strong>المدة</strong>. تخضع ملفات <code>.frec</code> للفحص المعمّق؛ أما الملفات الأخرى فتخضع لفحص البنية وفك الترميز عبر ffmpeg.","manual.0d291aee5546":"تصدير نسخة قابلة للمشاركة عند الإيقاف","manual.124d2a00ed27":"في <strong>الإعدادات ← الخرج</strong>، ومع ضبط الحاوية على <code>.frec</code>، حدّد <strong>احفظ أيضًا نسخة MP4 قابلة للمشاركة بجوار الملف الأصلي</strong>. عند انتهاء التسجيل، يكتب تصدير في الخلفية ملف <code>.mp4</code> يمكن لأي شخص تشغيله، بجوار الملف الأصلي بلا فقدان.","manual.a37303723389":"تظهر النسخة في قائمة انتظار ما بعد التسجيل، وتُسمّى بحيث لا تكتب فوق أي شيء أبدًا، ولا تلمس الملف الأصلي أبدًا. وهي معطَّلة حتى تفعّلها.","manual.7ed8656eb1ff":"رمز التوقيت SMPTE LTC","manual.3d97874c3064":"افتح <strong>رمز التوقيت SMPTE (LTC)</strong>، وفعّل <strong>توليد LTC على مسار</strong>، واختر مسار المازج ومعدل الإطارات لتغذية المسجّلات والكاميرات الخارجية. اضبط <strong>قراءة LTC من</strong> على مدخل صوتي لعرض سطر لرمز التوقيت في تراكب الإحصاءات ولختم علامات فصول LTC. رمز توقيت صوتي كلاسيكي، يعمل دون اتصال بالكامل، بدقة إطار واحد عند 24 و25 و30 fps.","manual.a9f690169703":"البث المباشر","manual.8f6df4580812":"بُثّ مباشرةً من الكمبيوتر إلى منصة عبر RTMP أو RTMPS — وليس أبدًا عبر خادم تابع لنا.","manual.dba22b61cdcc":"افتح <strong>الإعدادات ← البث</strong> وانقر <strong>إضافة وجهة</strong>. اختر <strong>Twitch</strong> أو <strong>YouTube</strong> أو <strong>Kick</strong> أو <strong>Facebook</strong> أو <strong>Trovo</strong> أو <strong>RTMP مخصص</strong>.","manual.2192731aac47":"الصق <strong>مفتاح البث</strong> — الذي يُحفظ على الكمبيوتر ويُعرض مُقنَّعًا — واضبط معدل البت والمُرمِّز لتلك الخدمة.","manual.040014e94f16":"انقر <strong>بدء البث</strong> في <strong>عناصر التحكم</strong>. يُضاء مؤشر <strong>مباشر</strong>، ويعرض رصيف الإحصاءات معدل البت والإطارات المُسقَطة وسلامة البث.","manual.0cd441959cb4":"إذا انقطع اتصالك، فإن Freally Capture <strong>يعيد الاتصال من تلقاء نفسه</strong>، ويستمر تسجيلك المحلي مهما حدث للبث. واضبط <strong>تأخير البث</strong> إن أردت ذلك.","manual.dc8ebcea4893":"انقر <strong>إنهاء البث</strong> للإيقاف.","manual.973adc03e43c":"أمان البث","manual.53fa9293a65e":"ألّا تخسر العرض — قبله وأثناءه وبعده.","manual.de8792b14216":"قبل البث: الفحص المسبق قبل بدء البث","manual.ed9a4b7bfaf5":"يؤدي النقر على <strong>بدء البث</strong> أولًا إلى تشغيل قائمة تحقق: لوجهات البث مفاتيح، وعُثر على مُرمِّز صالح للاستخدام، وكل مصدر سليم، وتوجد مساحة كافية على القرص للتسجيل — كلٌّ منها باللون الأخضر أو الأحمر، مع إصلاح بنقرة واحدة — إضافةً إلى تذكيرات بشأن مستويات الميكروفون وصوت سطح المكتب ومخزن الإعادة، وهي لا تمنع أبدًا عرضًا يقتصر على الشاشة. ويمكن لأحد الإعدادات أن <strong>يؤجّل بدء البث حتى تصبح كل الفحوص المانعة خضراء</strong>؛ وإلا فيتوفر خيار «بدء البث على أي حال».","manual.9b63c5c64ba1":"أثناء البث: التنبيهات والسلامة والتحويل عند الفشل","manual.9c386b745073":"تراقب <strong>تنبيهات الأمان</strong> أثناء البث المباشر أو التسجيل: صوت البرنامج الصامت، والتشبّع المستمر، والصورة السوداء أو المتجمدة، و<em>توقّع</em> انخفاض مساحة القرص («يتبقى نحو 22 دقيقة بمعدل البت الحالي»). تظهر على شكل لافتة يمكنك إغلاقها، وتعلن عنها قارئات الشاشة — وليست أبدًا مربع حوار يقاطع العرض.","manual.b7c8c66a5330":"تسرد <strong>لوحة معلومات سلامة المصادر</strong> (لوحة الأوامر ← «سلامة المصادر…») حالة كل مصدر، ومعدل إطاراته، وعمر آخر إطار له، والإطارات المُسقَطة، وعمليات إعادة التشغيل، مع <strong>إعادة تشغيل</strong> و<strong>الخصائص</strong> لكلٍّ منها.","manual.92bd60ef963b":"إذا تعطّل المُرمِّز العتادي في منتصف البث أو التسجيل — بسبب إعادة ضبط برنامج التشغيل، أو إجهاد بطاقة الرسومات — فإن <strong>التحويل عند فشل المُرمِّز</strong> ينتقل إلى مُرمِّز عتادي آخر أو إلى x264. يعيد البث الاتصال ويبقى قائمًا، ويستمر التسجيل في ملف جديد، وتوضح رسالة بالضبط ما حدث. ولا تتسبب مشكلات الشبكة أبدًا في التحويل.","manual.50a02fe4fe7b":"يقطع <strong>زر الطوارئ</strong> (اختصار عام تختاره) البرنامج — واللوحة الرأسية وأي أجهزة عرض — إلى شاشة خصوصية، ويوقف كل التقاط، ويكتم كل الصوت بما في ذلك الميكروفون، بينما يبقى البث والتسجيل متصلين. وتتطلب العودة تأكيدًا مقصودًا من خطوتين. اضبط لون الشاشة أو صورتها بجوار الاختصار في <strong>الإعدادات ← الاختصارات</strong>.","manual.a73a2857361e":"بعد البث: تسجيلات آمنة وإغلاق منظّم","manual.bf07b060e7e7":"تُكتب تسجيلات MP4 وMOV على شكل <strong>أجزاء</strong>، لذا يترك الانهيار أو انقطاع التيار ملفًا قابلًا للتشغيل (وكان هذا هو الحال أصلًا مع MKV و<code>.frec</code>). وإذا انتهت جلسة في منتصف تسجيل، فإن التشغيل التالي يعرض خيار <strong>إصلاح</strong> بنقرة واحدة إلى نسخة <code>(repaired)</code>؛ ولا يُمس الملف الأصلي أبدًا.","manual.da5eeb31c1b8":"يعرض الخروج أثناء البث المباشر أو التسجيل أو مع تجهيز الإعادة ما سيحدث، ثم يُغلق التطبيق <strong>بالترتيب</strong>: إنهاء البث، ثم إنهاء التسجيل، ثم حفظ مخزن الإعادة، ثم حفظ عملك.","manual.26b3f2c32e05":"تتبع <strong>أسماء ملفات التسجيل</strong> قالبًا (<strong>الإعدادات ← الخرج</strong>) مبنيًا من رموز — <code>{prefix}</code> <code>{date}</code> <code>{time}</code> <code>{scene}</code> <code>{profile}</code> <code>{canvas}</code> <code>{marker-count}</code> <code>{counter}</code> — للتسجيلات والإعادات والصور الثابتة، مع مجلدات خاصة بالإعادات والصور الثابتة.","manual.27c3f23547ac":"يحفظ <strong>تصدير بيانات التشخيص</strong> حزمة من التفاصيل التقنية في ملف على الكمبيوتر، مبنية من قائمة سماح صارمة بحيث لا تتضمن أبدًا مفاتيح البث أو كلمات المرور أو مسارات الملفات أو الأسماء. يمكنك قراءة محتواها أولًا؛ وتبقى حيث تحفظها ولا تُرسَل إلى أي مكان أبدًا.","manual.5199babf9b90":"المصادر والأجهزة","manual.306121fdda68":"كل ما بين العدسة واللوحة: إشارات الاختبار، ومعايرة المزامنة، والنص من ملف، والمؤقّتات، وخريطة الاختصارات، وإمكانات المازج المتقدمة، وعناصر تحكم حقيقية بالأجهزة.","manual.5eacf1ee941f":"إشارات الاختبار ومعايرة مزامنة الصوت والصورة","manual.920b7abd63cc":"أضف مصدر <strong>إشارة اختبار</strong> (<strong>المصادر ← + ← إشارة اختبار</strong>): أشرطة ألوان، أو شبكة معايرة، أو مسح حركي، أو نغمة ضبط بتردد 1 kHz عند −20 dBFS، أو <strong>وميض وصفير</strong> مدمجين لمزامنة الصوت والصورة — صورة وصوت ينبعان من ساعة واحدة. افحص جهاز عرض أو مُرمِّزًا أو وجهة بث دون توصيل أي كاميرا.","manual.788073298328":"افتح منضدة عمل <strong>معايرة مزامنة الصوت والصورة</strong> (لوحة الأوامر ← «معايرة مزامنة الصوت والصورة…»). اختر الكاميرا والميكروفون اللذين تريد محاذاتهما، ووجّه الكاميرا نحو البرنامج الوامض (يمكن لمربع الحوار فتح جهاز عرض بملء الشاشة لهذا الغرض)، ودعه يقيس لمدة اثنتي عشرة ثانية تقريبًا. يعثر على الوميض والصفير عبر عدة دورات ويعرض تطبيق الإزاحة المقيسة على الميكروفون؛ ويبقى شريط التمرير اليدوي خيارًا احتياطيًا. يجري القياس عبر شاشتك ومكبرات الصوت لديك، لذا فإن تأخيراتها الصغيرة جزء منه — وعند الفشل يوضح <em>السبب</em>.","manual.825c83c405fb":"المؤقّتات والساعات والنص من ملف","manual.85622b429b51":"يعرض مصدر <strong>مؤقّت</strong> أحد ما يلي: ساعة (بتنسيق من اختيارك وإزاحة UTC ثابتة اختيارية)، أو <strong>عدّ تنازلي</strong> (لمدة زمنية، أو حتى وقت محدد من اليوم — وعند الصفر يمكنه أن يومض أو يبدّل المشهد)، أو <strong>ساعة إيقاف</strong>، أو <strong>الوقت المنقضي منذ بدء البث المباشر أو التسجيل</strong>. ابدأه وأوقفه مؤقتًا وأعد ضبطه من <strong>الخصائص</strong> الخاصة به، أو اربط الاختصارين العامين اللذين يتحكمان في <em>كل</em> المؤقّتات معًا (<strong>الإعدادات ← الاختصارات</strong>).","manual.fcd4f802968f":"يمكن لمصدر <strong>نص</strong> أن <strong>يقرأ من ملف مراقَب</strong> (<strong>الخصائص ← القراءة من ملف</strong>): ملف <code>.txt</code> كامل، أو خلية CSV واحدة (حسب اسم العمود أو رقمه)، أو قيمة JSON واحدة (مؤشر مثل <code>/teams/0/score</code>). تظهر التغييرات خلال نصف ثانية. لوحات نتائج وأشرطة تعريفية سفلية دون أي خدمة وراءها.","manual.1d106549f0ce":"خريطة الاختصارات ووحدة تحكم المازج","manual.5d6ad89f147c":"تسرد <strong>خريطة الاختصارات</strong> (لوحة الأوامر ← «خريطة الاختصارات…») <em>كل</em> ربط — الإجراءات العامة واختصارات اضغط للتحدث واضغط للكتم لكل مصدر — مع إمكانية البحث والتصفية، وتشير إلى التعارضات بصدق: يُعرض الاختصار نفسه المكتوب بطريقتين على أنه مشترك، والمفتاح الذي رفضه النظام (لأن تطبيقًا آخر يحتكره) يُشار إليه بذلك. ويكتب <strong>تصدير ورقة مرجعية</strong> مرجعًا بصيغة Markdown في مجلد التنزيلات لديك.","manual.e32e382b9753":"يحتوي كل شريط في المازج على <strong>التحريك الأفقي</strong> (التوازن الستيريو؛ الوضع المركزي يعني انعدام التحريك تمامًا، والنقر المزدوج يعيد ضبطه)، و<strong>عزل PFL</strong> (لا تسمع المراقبة إلا الشرائط المعزولة؛ ولا يتغير مزيج البرنامج أبدًا)، و<strong>دمج أحادي</strong>. يوجد التحريك الأفقي والدمج الأحادي في قائمة «⋯» الخاصة بالشريط؛ أما العزل فعلى الشريط نفسه.","manual.5dbd70dfc92d":"إمكانات الأجهزة المتقدمة: إزالة التشابك وعناصر تحكم الكاميرا","manual.f8e60899a881":"توفر <strong>الخصائص</strong> الخاصة بجهاز التقاط الفيديو خيار <strong>إزالة التشابك</strong> للتغذيات المتشابكة، مثل بطاقات الالتقاط التي تغذيها كاميرات ومنصات ألعاب قديمة: الإسقاط، أو Bob، أو الخطي، أو المزج، أو التكيّف مع الحركة، مع ترتيب الحقول. يعمل بالطريقة نفسها على كل نظام؛ وتغييره يعيد تشغيل الجهاز.","manual.34192e6d30fd":"تظهر <strong>عناصر تحكم الكاميرا</strong> — التعريض، وتوازن اللون الأبيض، والتركيز، والتقريب، والكسب، وغيرها — في <strong>الخصائص</strong> نفسها أثناء تشغيل الكاميرا. يستخدم Windows وLinux عناصر تحكم UVC القياسية؛ أما macOS فيعرض ما يُبلغ عنه النظام، وهو في الغالب لا شيء، ويوضح القسم ذلك بدلًا من عرض أشرطة تمرير لا تفعل شيئًا. يُحفظ كل تعديل في <strong>ملف تعريف لتلك الكاميرا</strong>، ويُطبَّق مجددًا عند إعادة توصيلها أو إعادة تشغيل التطبيق؛ ويعيد <strong>إعادة ضبط الملف</strong> القيم الافتراضية.","manual.f77f10d8c967":"الأتمتة والتحكم","manual.726216fb4de1":"دع الاستوديو يدير نفسه بالقواعد والماكرو ووحدات التحكم العتادية — وكلٌّ منها مقيّد بقائمة واحدة ثابتة من أوامر الاستوديو، فلا يمكن لأي أتمتة أن تسمّي ملفًا أو تشغّل برنامجًا أو تصل إلى الإنترنت.","manual.193521bd4921":"القواعد والماكرو والمتغيرات","manual.e8ee7ccab125":"افتح <strong>أدوات ← قواعد الأتمتة والماكرو…</strong> وأضف قاعدة. اختر أحد تسعة مشغّلات (تبديل المشهد، أو بدء البث أو إيقافه، أو بدء التسجيل أو إيقافه، أو خطأ في مصدر، أو تجاوز مستوى الصوت لحدّ معين، أو دخول النظام في حالة خمول، أو حصول نافذة على التركيز، أو وقت محدد من اليوم، أو تغيّر ملف مراقَب)، وأضف شروطًا (قيمة متغير، أو البث المباشر، أو التسجيل)، واختر إجراءً من إجراءات الاستوديو. تبدأ كل قاعدة <strong>معطَّلة</strong>: فعّلها لتجهيزها.","manual.5deaa7ba718f":"أنشئ ماكرو على شكل قائمة مسمّاة من الخطوات — تشغيل إجراء، أو الانتظار، أو تعيين متغير — مع عدد مرات التكرار واختصار عام اختياري. شغّله من التطبيق، أو من اختصار، أو من قاعدة، أو من واجهة برمجة التحكم عن بُعد.","manual.30ee5b1326f2":"عيّن <strong>متغيرًا</strong> من متغيرات الاستوديو في ماكرو واستخدمه بصيغة <code>{{name}}</code> داخل أي مصدر نص: يتغير النص لحظة تعيين الماكرو للقيمة.","manual.5eb10fc04538":"وحدات التحكم: MIDI وOSC ولوحة اللمس","manual.ba0c838f1688":"افتح <strong>أدوات ← تحكم MIDI…</strong> وعلّمه لوحة ضغط أو مقبضًا دوارًا أو مُنزلِقًا لإجراء أو ماكرو أو تبديل مشهد أو مُنزلِق مستوى في المازج أو كتم — مع أضواء ومُنزلِقات آلية تتبع الحالة الفعلية للاستوديو. ولا يُفتح أي منفذ MIDI حتى تختار واحدًا.","manual.cc993cb0d974":"فعّل <strong>الاستماع إلى OSC</strong> للسماح لوحدات التحكم من نوع TouchOSC ومناضد الإضاءة بإرسال عناوين مثل <code>/scene/switch</code> و<code>/record/start</code> و<code>/macro/run</code> و<code>/mixer/vol</code>. يكون معطَّلًا افتراضيًا ولا يستمع إلا على هذا الكمبيوتر ما لم تسمح بشبكتك. ولا يملك OSC كلمة مرور خاصة به.","manual.134e5f4269f9":"افتح <strong>أدوات ← لوحة الشبكة وتالي…</strong> لتقديم صفحة تحكم — أزرار مشاهد مع مؤشرات تالي مباشرة، ومُنزلِقات المازج، ومفاتيح إجراءات — إلى أي هاتف عبر رمز QR. يتطلب كل طلب كلمة المرور، ولا يستمع إلا على هذا الكمبيوتر ما لم تسمح بشبكتك. تعرض صفحة التالي اللون الأحمر أو الأخضر بملء الشاشة؛ أضف <code>?scene=NAME</code> لمراقبة مشهد واحد.","manual.fc4cd96b860d":"الاختصارات المتسلسلة والطبقات","manual.ec4a9a334753":"في حقل اختصار، اربط اختصارًا بسيطًا (Ctrl+Shift+M) أو اختصارًا متسلسلًا من خطوتين (Ctrl+K ثم 3) — لا يُحجز المفتاح الثاني إلا أثناء انتظار التسلسل. امنح الربط <strong>طبقة</strong> كي يعمل فقط أثناء تنشيط تلك الطبقة؛ وتبقى الطبقات مفعّلة حتى تغيّرها.","manual.70ad05980925":"الكاميرات وجدول البرنامج","manual.24b33b058b99":"افتح <strong>أدوات ← كاميرات PTZ…</strong>، وأضف كاميرا بعنوان VISCA عبر IP الخاص بها، واحفظ إعدادات مسبقة مسمّاة للتحريك الأفقي والإمالة والتقريب، واربط إعدادًا مسبقًا بمشهد بحيث يستدعي الانتقال إلى ذلك المشهد اللقطة. يبقى PTZ ضمن شبكتك، ولا توجد الكاميرا إلا لأنك كتبت عنوانها: لا يُبحث عن أي شيء.","manual.c9d86b995c5a":"افتح <strong>أدوات ← إظهار جدول البرنامج…</strong> وأدرج الخطوات — مشهد، ومدة بقائه، وإجراءات اختيارية — مع التقدم يدويًا أو تلقائيًا، وعرض مباشر لـ«التالي» والوقت المتبقي. يبدّل جدول البرنامج المشاهد بالطريقة العادية القابلة للتراجع، ولا يحرّر مجموعة مشاهدك أبدًا.","manual.5c94bed2d737":"<strong>ملاحظة:</strong> تمر كل قاعدة وماكرو وربط MIDI أو OSC وزر في لوحة الشبكة وخطوة في جدول البرنامج عبر القائمة الثابتة نفسها من الأوامر التي تستخدمها واجهة برمجة التحكم عن بُعد، لذا لا يمكن لأي وحدة تحكم أن تفعل ما لا تستطيعه أزرار التطبيق نفسه. كل مستمع شبكة معطَّل افتراضيًا ويبقى على هذا الكمبيوتر ما لم تسمح بشبكتك، وتحذّرك إعدادات OSC ولوحة الشبكة من أن حركة مرور الشبكة غير مشفّرة قبل فتح المنفذ.","manual.1f3fd1c7ddc9":"البث المتعدد","manual.dcac0a03a29b":"بُثّ إلى عدة منصات في آنٍ واحد — مباشرةً من الكمبيوتر، دون أي خدمة ترحيل في المنتصف.","manual.42d9628818da":"أضف وجهتَي بث أو أكثر في <strong>الإعدادات ← البث</strong> وفعّل كلًّا منها.","manual.4144fe0d9694":"امنح المنصة إعدادات مُرمِّز خاصة بها إذا كانت تحتاج إلى معدل بت مختلف.","manual.cb21d6bb96be":"انقر <strong>بدء البث</strong>: تبث إلى كل وجهة مفعّلة في آنٍ واحد. يعرض رصيف الإحصاءات سلامة كل وجهة ومعدل البت الخاص بها، ولا يؤدي فشل وجهة واحدة أبدًا إلى إسقاط الوجهات الأخرى.","manual.aba9a5f55973":"يمكنك اختياريًا تسجيل نسخة محلية بمسارات منفصلة في الوقت نفسه، وحفظ الإعادات باختصار الإعادة أثناء البث.","manual.af9343c245a7":"<strong>مجاني اليوم:</strong> كل ميزة — البث المتعدد، وSRT وWHIP، وكل فلتر، والبرمجة النصية، والإعادة، وحزم الانتقالات، وواجهة برمجة التحكم عن بُعد — مجانية اليوم للجميع. وقد تُباع الإصدارات المستقبلية.","manual.c08320c45003":"موثوقية البث وتحليله","manual.532ab322d03c":"تدرّب على عرضك وقِسه وافهم ما يجري فيه. كل ما هنا معطَّل أو محايد افتراضيًا، ولا يتصل أي منه بالإنترنت.","manual.80390ae1a9d7":"محاكي الشبكة","manual.7e620ced841e":"في <strong>الإعدادات ← البث</strong>، افتح <strong>محاكي الشبكة (البروفات)</strong> واختر <strong>الملف</strong> — <strong>واي فاي فندق</strong> أو <strong>نقطة اتصال جوال</strong> أو <strong>مخصص</strong> مع قيمك الخاصة لـ<strong>عرض النطاق</strong> و<strong>زمن الانتقال</strong> و<strong>التذبذب</strong> وأوقات <strong>الانقطاع</strong> المجدولة. لا يؤثر إلا في الخرج المحلي للبروفة، لذا يمكنك التدرّب على إعادة الاتصال والبث المتعدد واختيارات معدل البت؛ ولا يمكنه أبدًا إبطاء بث حقيقي.","manual.b22d8c51e0bd":"وضع البروفة","manual.083772633b86":"اضغط زر <strong>بروفة</strong> البنفسجي لتشغيل خط المعالجة كاملًا — المُركِّب، والمُرمِّز، والدمج، ومنطق إعادة الاتصال الحقيقي — نحو بديل محلي <strong>دون أن يغادر أي شيء الكمبيوتر</strong>. تميّز شارة <strong>بروفة</strong> كل عنصر تحكم مباشر، ولا تُقرأ مفاتيح البث لديك أصلًا، لذا يمكنك التدرّب قبل أن تحصل عليها. ويمكنك أيضًا تسجيل البروفة.","manual.184d64047c4c":"<strong>نصيحة:</strong> اجمع بين البروفة ومحاكي الشبكة للتدرّب على إعادة الاتصال عبر اتصال ضعيف وغير مستقر قبل يوم العرض بوقت كافٍ.","manual.d2381a584d24":"الخط الزمني للإطارات المُسقَطة","manual.a6a72c5410a8":"يسجّل <strong>الخط الزمني للجلسة</strong> الجلسة بأكملها — زمن العرض، وقائمة انتظار المُرمِّز، ومعدل البت والإطارات المُسقَطة لكل وجهة، وعمليات إعادة الاتصال، وتبديلات المشاهد، والعلامات، والتنبيهات — على رسم بياني واحد قابل للتكبير. فبينما يعرض رصيف الإحصاءات ما يحدث <em>الآن</em>، يجيب الخط الزمني لاحقًا عن سؤال «ماذا حدث عند الدقيقة 43؟».","manual.6e9fee1e85fa":"تقرير الجلسة وقياس أداء المُرمِّزات","manual.9dd812cbf648":"فعّل <strong>كتابة تقرير للجلسة (HTML + Markdown) بجوار التسجيل</strong> في <strong>الإعدادات ← البث</strong> للحصول على ملخص محلي عند انتهاء الجلسة: مدة التشغيل، ومتوسط معدل البت وذروته لكل وجهة، والوقت المستغرق في الانقطاع، وعمليات إعادة الاتصال، والعلامات، والتنبيهات، وموقع التسجيل. يبقى التقرير على الكمبيوتر، وهو معطَّل افتراضيًا.","manual.a9e574b7bd8d":"استخدم <strong>تشغيل قياس أداء المُرمِّزات…</strong> لقياس عمليات ترميز قصيرة بكل مُرمِّز وإعداد مسبق ودقة يتيحها الكمبيوتر — نحو دقيقة، دون اتصال بالكامل — ثم اختر <strong>تطبيق على إعدادات التسجيل</strong> من النتيجة. تُدرج حالات الفشل ولا تُخفى، ويرفض قياس الأداء العمل أثناء البث المباشر أو التسجيل.","manual.fae310275ed2":"مصادر في البث فقط، أو في التسجيل فقط","manual.191da176dd0d":"في صف المصدر، استخدم <strong>إظهار في البث</strong> / <strong>إخفاء في البث</strong> و<strong>إظهار في التسجيل</strong> / <strong>إخفاء في التسجيل</strong> لإبقاء التنبيهات والدردشة في البث المباشر بينما يبقى التسجيل نظيفًا، من لوحة واحدة. يظل زر العين الرئيسي يتحكم في كل شيء، وتعرض المعاينة وأجهزة العرض والعرض المتعدد البرنامج كاملًا دائمًا.","manual.46bad2cb618f":"الكاميرا الافتراضية","manual.69ebe5277092":"استخدم برنامجك ككاميرا ويب في أي تطبيق لمكالمات الفيديو. <strong>Windows فقط في 1.2.1.</strong>","manual.ba2b6aa952f7":"انقر <strong>بدء الكاميرا الافتراضية</strong> في <strong>عناصر التحكم</strong>. يضيف Freally Capture كاميرا نظام باسم <strong>«Freally Capture Virtual Camera»</strong>.","manual.cb3cb4585f19":"في Zoom أو Meet أو Discord أو Teams، اختر تلك الكاميرا في إعدادات الفيديو: يصبح برنامجك هو كاميرا الويب.","manual.83db59f4a370":"انقر <strong>إيقاف الكاميرا الافتراضية</strong> لإزالتها.","manual.91c51d55639b":"<strong>حسب النظام:</strong> على <strong>Windows</strong> تُسجَّل الكاميرا لمستخدمك، دون صلاحيات المسؤول، وتُزال عند إيقافها. وهي <strong>غير موقّعة رقميًا بعد</strong>، لذا قد يحذّر Windows منها وقد يرفضها تطبيق مكالمات فيديو مُحصَّن؛ ولا يزال اختبار كامل داخل مكالمة حية مستحقًا. أما كاميرات <strong>macOS</strong> و<strong>Linux</strong> فهي مكوّنات منفصلة <em>غير مُضمَّنة في هذا الإصدار</em>. ولا يثبّت Freally Capture أبدًا مكوّن نظام دون أن يسألك، على أي نظام.","manual.98839b8e6880":"مصدر المتصفح","manual.3ba821584b20":"ضع صفحة ويب حية — تراكب تنبيهات، أو لوحة نتائج، أو أداة دردشة — مباشرةً في مشهد.","manual.895f07f428cd":"في <strong>المصادر</strong>، انقر <strong>+</strong> واختر <strong>متصفح</strong>.","manual.868ee19e975e":"الصق عنوانًا يبدأ بـ <strong>http://</strong> أو <strong>https://</strong> واضبط الحجم ومعدل الإطارات اللذين يُعرض بهما.","manual.292e94b0a782":"في المرة الأولى، يعرض Freally Capture تثبيت مكوّن <strong>وقت تشغيل المتصفح</strong>. يُنزَّل عندما تطلبه ويُتحقق منه مقابل التجزئة الخاصة به — ولا يُضمَّن أبدًا مع التطبيق — ويمكنك إزالته مجددًا من <strong>أدوات ← المكوّنات</strong>.","manual.cd6d7fbd46ee":"<strong>لا يُحمَّل سوى http وhttps.</strong> تشمل القاعدة كل تغيير للصفحة، لا العنوان الذي تكتبه فحسب: إذا حاولت صفحة الانتقال إلى <code>file://</code> أو <code>javascript:</code> أو <code>data:</code> — بإعادة توجيه، أو نص برمجي، أو نافذة منبثقة، أو إطار — فإن الانتقال <strong>يُلغى</strong>، فلا تستطيع الصفحة قراءة ملفاتك. على Windows تعمل الصفحة داخل وضع الحماية في Chromium. وقت التشغيل <strong>غير موقّع رقميًا بعد</strong>. ولا يُلتقط صوت الصفحة بعد: هذا الإصدار للصورة فقط.","manual.9c0c8f127dd9":"التقاط الألعاب","manual.2c08692420b8":"التقط لعبة تعمل بملء الشاشة الحصري لا يستطيع التقاط النوافذ العادي رؤيتها. <strong>Windows فقط.</strong>","manual.9d162e3861e9":"في <strong>المصادر</strong>، انقر <strong>+</strong> واختر <strong>التقاط لعبة</strong>. <strong>اقرأ الإشعار أولًا</strong>: فهو يشرح المخاطر بكلمات واضحة.","manual.4264b41a7732":"اقبل المخاطر <em>لتلك اللعبة وحدها</em>، ثم اختر اللعبة قيد التشغيل من القائمة.","manual.ab3e826e90f1":"يحمّل Freally Capture خطّافًا صغيرًا في تلك اللعبة ويلتقط إطاراتها بمعدل الإطارات الخاص باللعبة.","manual.082fd06e18f9":"<strong>اقرأ هذا قبل الاستخدام.</strong> يعمل التقاط الألعاب عبر <strong>تحميل مكتبة DLL داخل اللعبة</strong>. قد تعامل برامج مكافحة الغش ومكافحة الفيروسات ذلك على أنه عبث، وقد يؤدي إلى <strong>حظر</strong> الحساب. لا يُحمَّل أي شيء تلقائيًا أبدًا: توافق <strong>للعبة واحدة في كل مرة</strong>، ولا يمكن أبدًا استخدام تلك الموافقة للعبة أخرى — ولا تنتقل أبدًا ضمن مجموعة مشاهد مشتركة. وإذا رفضت لعبة الخطّاف، يتراجع Freally Capture إلى <strong>التقاط نافذة</strong> العادي مع رسالة بدلًا من الفشل. وتستخدم ألعاب HDR وألعاب Direct3D 12 التقاط نافذة أيضًا. ولا يُعرض هذا المصدر على macOS وLinux.","manual.43fae75af922":"مخزن الإعادة","manual.40bc664c1c0b":"احتفظ باللحظات الأخيرة في الذاكرة، كي يحفظ اختصار واحد ما حدث للتو.","manual.7a69241c10c2":"انقر <strong>بدء مخزن الإعادة</strong> في <strong>عناصر التحكم</strong>. يحتفظ Freally Capture بالثواني الأخيرة في مخزن مؤقت ذي حجم ثابت.","manual.684aecea2ba0":"اربط اختصار <strong>حفظ الإعادة</strong> العام في <strong>الإعدادات</strong>.","manual.66c44777e965":"اضغطه لحفظ الثواني الأخيرة في ملف — دون مقاطعة البث أو التسجيل الرئيسي. وتؤكد ذلك رسالة «حُفظت الإعادة».","manual.4b598d5daf11":"جهاز التلقين","manual.b7fc474ded62":"نص يمر بسلاسة للشخص أمام الكاميرا — على لوحة داخل التطبيق، وعلى جهاز عرض بملء الشاشة يمكن عكسه، وعلى لوحة اللمس عبر الشبكة المحلية، كلها في آنٍ واحد.","manual.f1c548f77750":"افتح جهاز التلقين من <strong>أدوات</strong>، واكتب نصك أو الصقه، واضبط السرعة والخط. حدّد الإيقاع بـ<strong>الأحرف في الثانية</strong>، أو انتقل إلى <strong>BPM</strong> (من 50 إلى 250 نبضة في الدقيقة) لقراءة كلمات الأغاني متزامنةً مع الموسيقى؛ وأي من التغييرين يعيد ضبط إيقاع التمرير الجاري.","manual.3a86eb91938d":"<strong>شرائح الإيقاف المؤقت:</strong> اكتب <code> -- </code> لوقفة قصيرة أو <code> --N </code> لتوقف مدته N ثانية فيتحول إلى شريحة واحدة — يتخطاها المؤشر، ويزيلها ضغط Delete أو Backspace مرة واحدة، ويحافظ النسخ واللصق عليها كاملة.","manual.dc7539148aed":"<strong>بدء العد التنازلي:</strong> جهّز عدًّا تمهيديًا اختياريًا 3-2-1، يظهر على معاينة المشغّل وعلى جهاز العرض معًا، كي يحظى القارئ بلحظة قبل أن يبدأ النص بالتحرك.","manual.f5113c573ac4":"<strong>افتح جهاز العرض</strong> للقارئ (يقلبه وضع العكس لزجاج تقسيم الشعاع). يؤدي فتحه إلى إغلاق نافذة المشغّل، لذا يمكنك إدارة البث من النافذة الرئيسية أثناء القراءة؛ ومع تجهيز العد التنازلي، يعود جهاز العرض إلى البداية، ويعدّ تنازليًا، ثم يبدأ التشغيل. شغّل، وأوقف مؤقتًا، وأوقف، وأرجِع، وقدّم سريعًا، وأعد البدء من عناصر التحكم على الشاشة، أو اختصار، أو MIDI، أو OSC، أو لوحة الشبكة — وتبقى كل عناصر التحكم متزامنة.","manual.5298a60b0152":"تتيح ميزة <strong>القراءة بصوت عالٍ</strong> معاينة النص باستخدام الكلام الخاص بنظامك: الأصوات المدمجة في Windows، وأصوات macOS، وعلى Linux <code>spd-say</code> أو <code>espeak-ng</code> حيثما كانا مثبّتين. ولا يُضمَّن أي محرك كلام.","manual.5de1b5efa245":"يقترح <strong>الإكمال التلقائي</strong> كلمات وعبارات باللون الرمادي الفاتح أثناء الكتابة؛ اضغط Tab للقبول. لكل لغة من اللغات الـ18 قاموسها الخاص على الكمبيوتر، ولا يُحمَّل إلا للغة التي تكتب بها.","manual.7fb5d22a1670":"التحكم عن بُعد","manual.b2ba73efdcec":"تحكّم في الاستوديو من Stream Deck أو من وحدة تحكم بأسلوب Companion — معطَّل افتراضيًا، ومحمي بكلمة مرور، وعلى الكمبيوتر الخاص بك.","manual.6396674fcd28":"افتح <strong>الإعدادات ← التحكم عن بُعد</strong>، وفعّل <strong>واجهة WebSocket البرمجية</strong> (معطّلة افتراضيًا)، واضبط <strong>كلمة المرور</strong>.","manual.56e0d6d295bb":"يستمع على <code>127.0.0.1</code> — هذا الكمبيوتر فقط — ما لم تسمح صراحةً بشبكتك.","manual.344e52e3eba1":"وجّه عميل Companion أو Stream Deck إلى العنوان المعروض. بدّل المشاهد، وشغّل الانتقالات، واكتم الصوت وألغِ كتمه، وابدأ التسجيل وأوقفه، واحفظ الإعادات من أزرار عتادية.","manual.6664edd9ad4c":"الضيوف عن بُعد وإنتاج العروض","manual.75ce17238f9b":"حوّل جلسة ضيوف عن بُعد إلى عرض مُنتَج: ما يصل إلى ثمانية ضيوف، والرسم على البرنامج المباشر، وغرفة انتظار، وإشارات خاصة، واتصال كل ضيف في لمحة، وشبكة تلقائية. كل ما هنا معطَّل أو غير مربوط افتراضيًا، ولا يتصل شيء حتى تدعو أحدًا.","manual.02d9e34002c8":"جلسات متعددة الضيوف","manual.5a6c2ec7640d":"ابدأ جلسة ضيوف عن بُعد وشارك رابط الدعوة أو رمز QR الخاص به: <strong>أنت وما يصل إلى ثمانية ضيوف</strong>، في معرض من واحد إلى تسعة. كل ضيف هو مربع له عناصر كتم خاصة به، وجودة اتصال، وقناة إشارات، وإدخال إلى الهواء بنقرة واحدة.","manual.34a323a45540":"يفتح الضيف الرابط في متصفح ويب — دون تثبيت أي شيء — وينقر <strong>انضمام</strong> لإرسال الكاميرا والميكروفون. ويمكن للضيف الذي يملك Freally Capture فتح الدعوة نفسها في التطبيق بدلًا من ذلك. وتنتهي صلاحية الدعوة بعد المدة التي تختارها.","manual.4e31042e4a6f":"<strong>ملاحظة:</strong> تنتقل الصورة والصوت مباشرةً بينك وبين كل ضيف، من نظير إلى نظير ومشفّرين أثناء النقل؛ ولا يمر عبر خدمة إرسال إشارات عامة سوى مصافحة الاتصال. اختُبرت الجلسات مع أربعة ضيوف؛ ويعتمد العدد الأكبر على عرض النطاق والمعالج لديك.","manual.33ff43cd0616":"أداة الرسم: ارسم على البرنامج المباشر","manual.d29f651d6eb9":"افتح <strong>أداة الرسم</strong> واختر أداة — <strong>قلم</strong> أو <strong>قلم تمييز</strong> أو <strong>سهم</strong> أو <strong>قطع ناقص</strong> — ثم ارسم مباشرةً على البرنامج. تصبح علاماتك جزءًا من الصورة لحظة رسمها، لذا تظهر في التسجيل والبث، لا في المعاينة فقط.","manual.9aa7fc0273fb":"اضبط العلامات على <strong>تلاشٍ</strong> بعد فترة، أو انتقل إلى <strong>وضع السبورة</strong> لاختيار <strong>إبقاء</strong> العلامات حتى تمسحها. يتبع الرسم ضغط القلم على اللوح الرقمي، ويمكن ربط <strong>مسح العلامات</strong> باختصار (غير مربوط افتراضيًا).","manual.fc81cd8d37ae":"غرفة الانتظار","manual.c87beb96ec64":"فعّل <strong>غرفة الانتظار</strong> فينتظر الضيوف الجدد خارج الهواء بينما تتحقق من الكاميرا والميكروفون لديهم في <strong>معاينة غرفة الانتظار</strong>. وعندما يكونون جاهزين، انقر <strong>أدخِل على الهواء</strong>. يرى الضيف لافتة «أنت في غرفة الانتظار»، في التطبيق أو على صفحة الويب.","manual.1d47c8224f50":"الإشارات والتحدث","manual.569d461035c1":"أرسل إلى ضيف <strong>إشارة</strong> خاصة — مع إعدادات مسبقة مثل <strong>30 ثانية</strong> و<strong>اختم</strong> و<strong>دورك التالي</strong> و<strong>ارفع صوتك</strong> — عبر قناة الجلسة الحالية من نظير إلى نظير. يراها الضيف مع عدّ تنازلي مباشر، ولا تظهر في البرنامج أبدًا.","manual.c66c9d5359bf":"لوحة معلومات جودة الاتصال","manual.4541cc1ee0f5":"راقب اتصال كل ضيف مباشرةً — زمن الذهاب والإياب، وفقدان الحزم، والدقة ومعدل الإطارات اللذين تستقبلهما، والتذبذب — مع شارة خضراء أو كهرمانية أو حمراء ورسم بياني صغير للسجل، كي يظهر ضعف الاتصال قبل أن يلاحظه مشاهدوك.","manual.bf8e764221e5":"شبكات الضيوف التلقائية","manual.ffe3c227cdfc":"فعّل <strong>شبكة تلقائية</strong> لإبقاء الضيوف الموجودين على الهواء في شبكة مرتبة من واحد إلى تسعة تعيد ترتيب نفسها عند انضمام الضيوف أو مغادرتهم أو إدخالهم إلى الهواء، أو اضغط زر الترتيب لفعل ذلك الآن. ينشر كل مقعد اسم ضيفه كمتغير <code>{{guestN}}</code>، لذا يتحول مصدر العنوان إلى لوحة اسم تتحدّث من تلقاء نفسها.","manual.e8630fabd4e5":"إدارة الاستوديو وسير العمل","manual.c8c487196725":"اجعل تخطيطًا كاملًا قابلًا للنقل والمشاركة، واحتفظ بإصدارات مسمّاة من مشاهدك، وخصّص سمة التطبيق، وضع إجراءاتك المفضلة على بُعد نقرة واحدة — كل ذلك على الكمبيوتر، دون أي خادم.","manual.f87995a7cf6c":"حزم المشاهد وإصداراتها","manual.074bb2bf9453":"افتح مربع حوار مساحة العمل من <strong>مجموعة المشاهد ← إدارة مجموعات المشاهد…</strong>: تجد هناك جميع أدوات الحزم والمقارنة واللقطات والنسخ الاحتياطي وتخطيطات الإرساء.","manual.8dce3a052a05":"انقر <strong>تصدير الحزمة…</strong> لتجميع المجموعة الحالية وملفاتها (الصور، والوسائط، وملفات LUT، والأقنعة، والخطوط) في ملف <code>.fcappack</code> واحد قابل للنقل. تُدرج عناوين الويب ومسارات الشبكة على أنها <em>خارجية</em> بدلًا من تضمينها، ويُشار إلى الخطوط بسبب تراخيصها.","manual.c1bba88df9c5":"انقر <strong>استيراد حزمة…</strong> واختر ملف <code>.fcappack</code>: تصل الحزمة كمجموعة جديدة، وتعثر على ملفاتها على هذا الكمبيوتر، ويُنتقل إليها.","manual.69e7b9f6e8ab":"انقر <strong>مقارنة ودمج…</strong> لمقارنة المجموعة الحالية بمجموعة أخرى أو حزمة أو لقطة. راجع المشاهد والمصادر والتحويلات والفلاتر وحالات الظهور المضافة والمحذوفة والمتغيرة، ثم اختر بالضبط التغييرات التي تريد جلبها. واختيار مشهد يجلب المصادر التي يستخدمها.","manual.862a75c84629":"انقر <strong>اللقطات…</strong>، وسمِّ نقطة حفظ واختر <strong>حفظ اللقطة</strong>. ويعيدها خيار <strong>استعادة</strong> لاحقًا — إذ يُحفظ تخطيطك الحالي كلقطة أولًا، لذا لا تكون الاستعادة باتجاه واحد أبدًا. يُحتفظ بما يصل إلى 50 لقطة، مع عرض المساحة التي تشغلها على القرص.","manual.8058b1480d14":"<strong>نصيحة:</strong> اللقطات سجل مسمّى إلى جانب الحفظ التلقائي والتراجع. التقط واحدة قبل أي تغيير محفوف بالمخاطر، فتكون لديك دائمًا نقطة معنونة للعودة إليها.","manual.1d55a62a5fdf":"النسخ الاحتياطي والاستعادة والوضع المحمول","manual.250b89a976de":"في مربع حوار مساحة العمل، انقر <strong>النسخ الاحتياطي والاستعادة…</strong>، ثم <strong>تصدير نسخة احتياطية…</strong> لحفظ كل شيء — الإعدادات وملفات التعريف ومجموعات المشاهد — في ملف <code>.fcapbackup</code> واحد.","manual.560e7e269f11":"على كمبيوتر جديد، انقر <strong>الاستعادة من نسخة احتياطية…</strong>، وحدّد ما تريد جلبه (<strong>الإعدادات</strong> و<strong>مجموعات المشاهد</strong> و<strong>ملفات التعريف</strong>) واختر <strong>استعادة المحدد</strong>. ثم أعد تشغيل Freally Capture لتحميل المجموعات وملفات التعريف المستعادة.","manual.5b26da4b8793":"للتشغيل من ذاكرة USB، ضع ملفًا باسم <code>freally-portable.txt</code> بجوار البرنامج: ستُخزَّن حينها كل بياناته في مجلد البرنامج بدلًا من ملف تعريف المستخدم لديك. ويعرض <strong>الإعدادات ← حول</strong> ما إذا كان الوضع المحمول مفعّلًا ومكان البيانات.","manual.a31a49d41d7d":"<strong>ملاحظة:</strong> لا تُكتب مفاتيح البث وكلمات المرور أبدًا في نسخة احتياطية — أدخلها مجددًا بعد الاستعادة.","manual.5b446c4ea972":"السمات والتخطيطات والإجراءات السريعة","manual.8eea476bde73":"افتح <strong>الإعدادات ← المظهر</strong> واختر السمة <strong>مخصص</strong> لتحرير لوحة الألوان، مع <strong>تحذيرات التباين</strong> المباشرة، ثم <strong>تصدير .fctheme…</strong> أو <strong>استيراد .fctheme…</strong> لمشاركتها.","manual.7cc0bc3a4e74":"في <strong>تخطيطات الإرساء</strong> ضمن مربع حوار مساحة العمل، احفظ الترتيب الحالي باسم، وانقر تخطيطًا محفوظًا للانتقال إليه.","manual.c9044c09b979":"في <strong>الإعدادات</strong>، اكتب في <strong>بحث في الإعدادات…</strong> للانتقال إلى أي إعداد؛ وتوضح علامةٌ الفئات التي غيّرتها منذ فتحه.","manual.a4640858ad4d":"اختر <strong>أدوات ← إجراءات سريعة…</strong> لفتح شبكة الأزرار. انقر <strong>تحرير</strong>، ثم <strong>إضافة زر</strong>، واضبط تسمية كل زر ولونه، وأضف <strong>صفحات</strong>. يمكن للزر تبديل مشهد، أو تشغيل ماكرو، أو تشغيل وسادة من لوحة المؤثرات الصوتية، أو تنفيذ أمر من أوامر الاستوديو.","manual.74ff6472576d":"<strong>نصيحة:</strong> تنفّذ أزرار الإجراءات السريعة أوامر الاستوديو نفسها التي تنفّذها الاختصارات، والشبكة مشتركة مع لوحة اللمس عبر الشبكة المحلية: اضبطها مرة واحدة فتجدها على هاتفك أيضًا.","manual.74a883a037bc":"الإعدادات","manual.5feaf4600834":"ملفات التعريف، ومجموعات المشاهد، والاختصارات، واللغة. كل شيء مجاني اليوم، لذا لا يوجد ما يلزم تفعيله. <strong>الإعدادات</strong> نافذة واحدة مقسّمة إلى فئات — عام، والمظهر، والبث، والخرج، والإعادة، والاختصارات، والشبكة، وإمكانية الوصول، وحول — وتُفتح من <strong>شريط القوائم</strong> (ملف، وتحرير، وعرض، والأرصفة، وملف التعريف، ومجموعة المشاهد، وأدوات، ومساعدة).","manual.9f6a04e85e39":"<strong>«تطبيق» يعني التطبيق فعلًا.</strong> تحرّر نافذة الإعدادات نسخة: لا يتغير شيء حتى تنقر <strong>تطبيق</strong> أو <strong>موافق</strong>، ويعيد <strong>إلغاء</strong> بالضبط ما كان لديك، بما في ذلك معاينة السمة.","manual.3fc0968ef6f9":"<strong>ملفات التعريف ومجموعات المشاهد:</strong> احتفظ بإعدادات منفصلة — «البث» و«التسجيل المحلي» مثلًا — وبدّل بينها دون إعادة التشغيل، من قائمتَي <strong>ملف التعريف</strong> و<strong>مجموعة المشاهد</strong>.","manual.ce6f52861bdb":"<strong>الاختصارات:</strong> اربط كل إجراء من قائمة لا يمكن أن تتعارض — اختر اختصارًا لإجراء واحد فيختفي من قائمة كل إجراء آخر، فلا تشترك ميزتان أبدًا في مفتاح واحد. ويحرّره خيار <strong>بلا</strong> مجددًا.","manual.be52349f05be":"<strong>إمكانية الوصول:</strong> اختر ألوان مقاييس المازج، بما في ذلك مجموعة آمنة لمصابي عمى الألوان. يعمل التطبيق بأكمله من لوحة المفاتيح، وتعلن قارئات الشاشة عن بدء البث المباشر، والتسجيل، وإعادة الاتصال، والإطارات المُسقَطة.","manual.a79c94673558":"<strong>اللغة:</strong> اختر إحدى 18 لغة؛ يتغير التطبيق فورًا، وتُقرأ العربية من اليمين إلى اليسار.","manual.59274c49ac87":"الإبلاغ عن مشكلة","manual.c02ed8aec89d":"أنت من يقرر ما إذا كانت المشكلة تصل إلى المطوّر، وترى بالضبط ما سيُرسَل.","manual.4ed327c34aeb":"عندما يعرض التطبيق خطأً تسبّب فيه بنفسه، يظهر زر <strong>إبلاغ</strong> بجانبه.","manual.95da4b53fdcc":"بعد حدوث انهيار، يعرض التشغيل التالي <strong>إبلاغ</strong> أو <strong>تجاهل</strong>.","manual.6207904599f4":"يفتح <strong>إبلاغ</strong> صفحة الإبلاغ الخاصة بـ Freally Capture على هذا الموقع في متصفحك، مع ملء التفاصيل التقنية مسبقًا: يمكنك قراءتها، لكن لا يمكنك تغييرها. أضف ما كنت تفعله، وعنوان بريد إلكتروني إن أردت. لا يُرسَل أي شيء ما لم تضغط <strong>إرسال</strong> هناك.","manual.6acd4e789ccd":"لا يُرسَل أي شيء في الخلفية أبدًا، ولا يرسل <strong>تجاهل</strong> أي شيء على الإطلاق.","manual.69bd78234ffb":"الخصوصية والشبكة","manual.42f9b04c2640":"لا يوجد في Freally Capture حساب ولا قياس عن بُعد (telemetry)، ولا توجد لدينا أي خدمة سحابية. إليك بالضبط ما يتصل بالإنترنت، وما لا يتصل.","manual.81fe73d241a8":"<strong>لا حساب، ولا قياس عن بُعد.</strong> لا يطلب منك التطبيق تسجيل الدخول أبدًا، ولا يرسل مشاهدك أو تسجيلاتك أو أي بيانات استخدام إلى أي مكان أبدًا.","manual.3735a28566e9":"<strong>يذهب بثك مباشرةً إلى المنصة.</strong> ينتقل من الكمبيوتر إلى الخدمات التي تضبطها — ولا يوجد أي خادم ترحيل تابع لنا.","manual.512b8fa00684":"<strong>تبقى تسجيلاتك على الكمبيوتر</strong>، في المجلد الذي تختاره. ولا يُرفع أي شيء.","manual.c299fcfa1fde":"<strong>تبقى مفاتيح البث على الكمبيوتر</strong>، وتُعرض مُقنَّعة ولا تُرسَل إلا إلى الخدمة التي تبث إليها.","manual.414a08bd0219":"<strong>يتصل الضيوف عن بُعد من نظير إلى نظير.</strong> لا يمر عبر خدمة إرسال إشارات عامة سوى مصافحة الجلسة، وذلك فقط عندما تبدأ جلسة.","manual.20c95c4687b3":"<strong>يقرأ تراكب الدردشة الدردشة العامة</strong> من القناة التي توجّهه إليها، كما يفعل مشاهد غير مسجّل الدخول — دون حساب أو مفتاح أو تسجيل دخول.","manual.efe87d55bed1":"<strong>لا يُنزَّل مكوّنان إلا عندما تحتاج إليهما لأول مرة:</strong> ffmpeg، لبرامج الترميز التي تتطلبها المنصات، ووقت تشغيل المتصفح، لمصدر المتصفح. يأتي كلٌّ منهما من ناشره الخاص ويُتحقق منه قبل الاستخدام.","manual.3601a272b3b0":"<strong>يجلب التحقق من التحديثات</strong> ملفًا صغيرًا واحدًا مرة في كل تشغيل، وعندما تختار <strong>تحقّق من التحديثات…</strong>. لا يُرسَل معه أي شيء عنك أو عن الكمبيوتر، ولا يُثبَّت أي شيء ما لم توافق.","manual.11abc96d8e21":"<strong>لا يُرسَل تقرير المشكلة إلا عندما تضغط «إرسال»</strong> في صفحة الإبلاغ، بعد أن تقرأ ما يحتويه (راجع <a href=\"#report\">الإبلاغ عن مشكلة</a>).","manual.804fa6536d40":"<strong>لا ذكاء اصطناعي.</strong> كل فلتر — كبت الضوضاء، ومفتاح الكروما، وتعيين درجات الألوان — هو معالجة إشارات كلاسيكية. لا يحتوي التطبيق على أي نموذج تعلّم آلي ولا يُنزّل أي نموذج."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
